function jumpResearch(id){const c=document.getElementById(id);c?.scrollIntoView({behavior:reduced.matches?"auto":"smooth",block:"center"});c?.classList.add("target-flash");setTimeout(()=>{c?.classList.remove("target-flash");openResearch(id)},260)}
function jumpSchedule(id){
 const idx=DATA.days.findIndex(d=>d.events.some(e=>e.id===id));
 if(idx>=0)renderDay(idx);
 setTimeout(()=>{const e=document.getElementById(id)||$("#schedule");e?.scrollIntoView({behavior:reduced.matches?"auto":"smooth",block:"center"});e?.classList.add("target-flash");setTimeout(()=>e?.classList.remove("target-flash"),900)},80);
}
function base64Bytes(v){const b=atob(v);return Uint8Array.from(b,ch=>ch.charCodeAt(0))}
async function decryptEmergency(p){
 const m=await crypto.subtle.importKey("raw",new TextEncoder().encode(p),"PBKDF2",false,["deriveKey"]);
 const k=await crypto.subtle.deriveKey({name:"PBKDF2",salt:base64Bytes(DATA.encryptedContacts.salt),iterations:180000,hash:"SHA-256"},m,{name:"AES-GCM",length:256},false,["decrypt"]);
 const plain=await crypto.subtle.decrypt({name:"AES-GCM",iv:base64Bytes(DATA.encryptedContacts.iv),tagLength:128},k,base64Bytes(DATA.encryptedContacts.data));
 return JSON.parse(new TextDecoder().decode(plain));
}
async function unlock(){
 const s=$("#emergencyStatus"),c=$("#emergencyContent");s.textContent="正在验证…";
 try{const rows=await decryptEmergency($("#emergencyPassword").value);c.innerHTML=`<div class="table-wrap"><table><thead><tr><th>成员</th><th>亲属紧急联系人</th><th>关系</th><th>紧急电话</th></tr></thead><tbody>${rows.map(r=>`<tr>${[r[0],r[2],r[3],r[4]].map(x=>`<td>${esc(x)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;c.hidden=false;s.textContent="已解锁。用完请重新锁定。"}catch{c.hidden=true;c.innerHTML="";s.textContent="密码不正确。请检查后再试。"}
}
function lock(){ $("#emergencyPassword").value="";$("#emergencyContent").hidden=true;$("#emergencyContent").innerHTML="";$("#emergencyStatus").textContent="已重新锁定。"}
let corpus=[];
function buildSearch(){
 corpus=[...DATA.days.flatMap((d,di)=>d.events.map(e=>({type:"行程",title:`${d.date} ${e.place}`,text:JSON.stringify({...d,...e}),day:di,target:e.id}))),...DATA.phrases.map(p=>({type:"常用语",title:p[0],text:p.join(" "),target:"prepare"})),...DATA.signs.map(p=>({type:"标识",title:p[0],text:p.join(" "),target:"greekSigns"})),...DATA.supportPacking.map(p=>({type:"物资",title:p[0],text:p.join(" "),target:"support-details",open:true})),...DATA.personalPacking.map(p=>({type:"物资",title:p[0],text:p.join(" "),target:"packing-details",open:true})),...DATA.contacts.map(p=>({type:"成员",title:p[0],text:p.join(" "),target:"contacts-details",open:true})),...Object.entries(DATA.transport).map(([city,t])=>({type:"交通",title:t.title,text:JSON.stringify(t),target:"transportPanel",city})),...DATA.safetyGroups.map(g=>({type:"安全",title:g.title,text:g.items.join(" "),target:g.id,open:true})),...DATA.publicPhones.map(p=>({type:"电话",title:`${p[0]} ${p[1]}`,text:p.join(" "),target:`phone-${String(p[3]).replace(/\D/g,"")}`})),...DATA.research.map(r=>({type:"调研",title:`${r.date} ${r.title}`,text:JSON.stringify(r),target:r.id,researchId:r.id}))];
}
function runSearch(){
 const kw=$("#searchInput").value.trim().toLowerCase(),out=$("#searchResults");
 if(!kw){out.innerHTML='<p class="empty">输入关键词即可检索行程、物资、交通、安全和调研资料。</p>';return}
 const ms=corpus.filter(x=>x.text.toLowerCase().includes(kw)||x.title.toLowerCase().includes(kw)).slice(0,24);
 out.innerHTML=ms.length?ms.map((m,i)=>`<button class="search-result" type="button" data-result="${i}"><small>${esc(m.type)}</small><strong>${esc(m.title)}</strong></button>`).join(""):'<p class="empty">没有找到相关内容。</p>';
 $$(".search-result",out).forEach((b,i)=>b.addEventListener("click",()=>jumpResult(ms[i])));
}
let returnFocus=null;
function openSearch(){returnFocus=document.activeElement;$("#searchOverlay").classList.add("is-open");$("#searchOverlay").setAttribute("aria-hidden","false");document.body.classList.add("search-open");setTimeout(()=>$("#searchInput")?.focus(),120)}
function closeSearch(restore=true){$("#searchOverlay").classList.remove("is-open");$("#searchOverlay").setAttribute("aria-hidden","true");document.body.classList.remove("search-open");if(restore)returnFocus?.focus?.()}
function jumpResult(it){
 if(Number.isInteger(it.day))renderDay(it.day);if(it.city)renderTransport(it.city);
 if(it.researchId){closeSearch(false);setTimeout(()=>jumpResearch(it.researchId),180);return}
 const t=document.getElementById(it.target);if(t?.tagName==="DETAILS"||it.open)t.open=true;
 closeSearch(false);setTimeout(()=>{t?.scrollIntoView({behavior:reduced.matches?"auto":"smooth",block:"center"});t?.classList.add("target-flash");setTimeout(()=>t?.classList.remove("target-flash"),900)},180);
}
let currentPhraseAudio=null,currentPhraseButton=null;
function resetPhraseButton(btn){if(btn){btn.classList.remove("is-playing");btn.textContent="播放"}}
function speakFallback(btn){
 if(!("speechSynthesis"in window)||!btn.dataset.speech){btn.textContent="不可用";btn.classList.remove("is-playing");return}
 speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(btn.dataset.speech);u.lang="el-GR";u.rate=.86;
 const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang&&v.lang.toLowerCase().startsWith("el"))||null;
 u.onend=()=>resetPhraseButton(btn);u.onerror=()=>{btn.textContent="不可用";btn.classList.remove("is-playing")};speechSynthesis.speak(u);
}
function play(btn){
 if(currentPhraseAudio){currentPhraseAudio.pause();currentPhraseAudio.currentTime=0;resetPhraseButton(currentPhraseButton)}
 if(currentPhraseButton===btn){currentPhraseAudio=null;currentPhraseButton=null;return}
 btn.classList.add("is-playing");btn.textContent="播放中";currentPhraseButton=btn;
 const src=btn.dataset.audio;
 if(!src){speakFallback(btn);return}
 const audio=new Audio(src);currentPhraseAudio=audio;
 audio.addEventListener("ended",()=>{resetPhraseButton(btn);if(currentPhraseAudio===audio){currentPhraseAudio=null;currentPhraseButton=null}});
 audio.addEventListener("error",()=>speakFallback(btn),{once:true});
 audio.play().catch(()=>speakFallback(btn));
}
function openImageViewer(trigger){
 const overlay=$("#imageViewer"),img=$("#imageViewerImage"),title=$("#imageViewerTitle"),address=$("#imageViewerAddress");
 const source=trigger.querySelector("img"),caption=trigger.closest("figure, .hotel")?.querySelector("figcaption, h3");
 if(!overlay||!img||!source)return;
 img.src=source.currentSrc||source.src;img.alt=source.alt||"";
 title.textContent=caption?.querySelector?.("strong")?.textContent||caption?.textContent?.trim()||source.alt||"图片";
 address.textContent=caption?.textContent?.replace(title.textContent,"").trim()||"";
 overlay.classList.add("is-open");overlay.setAttribute("aria-hidden","false");document.body.classList.add("image-viewer-open");
 $("#closeImageViewer")?.focus({preventScroll:true});
}
function closeImageViewer(){
 const overlay=$("#imageViewer");if(!overlay)return;
 overlay.classList.remove("is-open","is-closing");overlay.setAttribute("aria-hidden","true");document.body.classList.remove("image-viewer-open");
}
function observers(){
 document.body.classList.add("motion-ready");requestAnimationFrame(()=>document.body.classList.add("is-ready"));
 const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add("is-visible")}),{threshold:.08});$$(".reveal").forEach(e=>io.observe(e));
 const ids=["schedule","prepare","safety","research"],sio=new IntersectionObserver(es=>{const h=es.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(!h)return;const i=ids.indexOf(h.target.id);$$(".dock a").forEach((a,n)=>a.classList.toggle("is-active",n===i));$(".dock")?.style.setProperty("--dock-index",Math.max(0,i))},{rootMargin:"-45% 0px -45% 0px",threshold:[.01,.2,.6]});
 ids.forEach(id=>{const e=document.getElementById(id);if(e)sio.observe(e)});
 addEventListener("scroll",()=>{$(".topbar")?.classList.toggle("is-scrolled",scrollY>12);const h=document.documentElement.scrollHeight-innerHeight;$(".scroll-progress span")?.style.setProperty("transform",`scaleX(${h?scrollY/h:0})`)},{passive:true});
}
function init(){
 set("#dayTabs",DATA.days.map((d,i)=>`<button class="tab-button ${i===0?"is-active":""}" type="button" role="tab" aria-selected="${i===0}" data-index="${i}">${esc(d.date)}</button>`).join(""));
 set("#phrases",DATA.phrases.map(([cn,gr],i)=>`<article class="phrase-card ${(Math.floor(i/2)+i%2)%2===0?"is-dark":"is-light"}"><div><strong>${esc(cn)}</strong><span>${esc(gr)}</span></div><button class="phrase-play" type="button" data-audio="assets/audio/greek/${phraseAudioFiles[i]}.mp3" data-speech="${esc(speech(gr))}">播放</button></article>`).join(""));
 set("#greekSigns",DATA.signs.map(([cn,gr],i)=>`<article class="sign-card ${i%2===0?"is-light":"is-dark"}"><span>${esc(cn)}</span><strong>${esc(gr)}</strong></article>`).join(""));
 checks("supportPacking",DATA.supportPacking,"support");checks("personalPacking",DATA.personalPacking,"personal");
 set("#contactsTable",DATA.contacts.map(r=>`<tr>${r.map((c,i)=>i===4?`<td><a class="member-phone" href="tel:${esc(String(c).replace(/\s/g,""))}">${esc(c)}</a></td>`:`<td>${esc(c)}</td>`).join("")}</tr>`).join(""));
 set("#safetyGroups",DATA.safetyGroups.map(g=>`<details id="${esc(g.id)}"><summary>${esc(g.title)} <span class="tag muted">${esc(g.range)}</span></summary><div class="details-body"><ul>${g.items.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div></details>`).join(""));
 set("#publicPhones",DATA.publicPhones.map(([n,t,b,d])=>`<article class="phone-card" id="phone-${esc(String(d).replace(/\D/g,""))}"><div class="phone-number">${esc(n)}</div><h3>${esc(t)}</h3><p>${esc(b)}</p><a class="call-link" href="tel:${esc(d)}"><img src="assets/icons/phone.svg" alt="">拨打</a></article>`).join(""));
 renderResearch();renderDay(0);renderTransport("athens");buildSearch();observers();
}
init();
